   if(EditorApplication.timeSinceStartup<wait)return;
   if(stage==0){
    var run=flow.CurrentRun;run.RecordBattleVictory(run.CurrentHP,200);flow.ShowLobby();Check(flow.Session.HasSavedRun,"lobby keeps challenge");Check(flow.Session.Profile.bestScore==0&&flow.Session.Profile.bestBond==0,"lobby never finalizes maxima");
    var saved=new ProfileStore(Prefix).Load();Check(saved.activeRun.progress.runId==run.Progress.runId,"run persisted");flow.ResumeRun();Check(flow.CurrentRun.Progress.runId==run.Progress.runId&&flow.CurrentRun.Level==run.Level,"resume unchanged");flow.ShowLobby();run.End();flow.Session.FinishRun(run);int score=flow.Session.Profile.bestScore;flow.Session.FinishRun(run);Check(score>0&&score==flow.Session.Profile.bestScore&&!flow.Session.HasSavedRun,"death finalizes once");Check(flow.Session.Profile.pendingLeaderboardRecords.Count==0,"no submission queue");
