    OfflineRecords.ApplyFinished(p,Record("a",1000,3,4,"ember"));OfflineRecords.ApplyFinished(p,Record("b",500,20,25,"okta"));Check(p.bestScore==1000&&p.bestFloor==20&&p.bestBond==25&&p.bestScoreRun.dragonId=="ember","independent maxima same-run partner");OfflineRecords.ApplyFinished(p,Record("c",2000,10,12,"zephyr"));Check(p.bestScoreRun.dragonId=="zephyr"&&p.bestFloor==20&&p.bestBond==25,"different dragon higher score");
    new ProfileStore(Prefix+".Records").Save(p);var restored=new ProfileStore(Prefix+".Records").Load();Check(restored.bestScoreRun.customDragonName=="별빛친구"&&restored.bestFloor==20,"record reload");
    string owner="test:previous",source=Prefix+".Account."+LocalTrainerSave.Key(owner),dest=Prefix+".Offline."+LocalTrainerSave.Key(owner);foreach(var s in new[]{".A",".B"})PlayerPrefs.DeleteKey(dest+s);var originalStore=new ProfileStore(source);originalStore.Load();originalStore.Save(saved);string rawA=PlayerPrefs.GetString(source+".A"),rawB=PlayerPrefs.GetString(source+".B");string copy=OfflineRecords.CopyAccount(Prefix,owner);Check(copy==dest&&new ProfileStore(dest).Load().hasActiveRun,"account resume copied");Check(rawA==PlayerPrefs.GetString(source+".A")&&rawB==PlayerPrefs.GetString(source+".B"),"original account untouched");Check(OfflineRecords.Meaningful(flow.Session.Profile),"conflict detected");var destStore=new ProfileStore(dest);var d=destStore.Load();d.playerName="수정된로컬";destStore.Save(d);OfflineRecords.CopyAccount(Prefix,owner);Check(new ProfileStore(dest).Load().playerName=="수정된로컬","existing migration never overwritten");
    string corruptOwner="test:corrupt",bad=Prefix+".Account."+LocalTrainerSave.Key(corruptOwner);PlayerPrefs.SetString(bad+".A","broken");PlayerPrefs.DeleteKey(bad+".B");bool threw=false;try{OfflineRecords.CopyAccount(Prefix,corruptOwner);}catch{threw=true;}Check(threw&&PlayerPrefs.GetString(bad+".A")=="broken","corrupt retained");
    var legacy=ProfileStore.Clone(p);legacy.localRecordsVersion=0;legacy.bestScore=9999;legacy.bestScoreRun=null;new ProfileStore(Prefix+".Legacy").Save(legacy);var session=new CollectionSession(new ProfileStore(Prefix+".Legacy"),ContentDatabase.Load().dragons);session.PrepareOfflineRecords();Check(session.Profile.bestScore==9999&&(session.Profile.bestScoreRun==null||string.IsNullOrEmpty(session.Profile.bestScoreRun.runId)),"unknown legacy partner not invented");
    var displayStore=new ProfileStore(Prefix);displayStore.Load();displayStore.Save(p);Call("OpenOfflineStore",Prefix);wait=EditorApplication.timeSinceStartup+.7;stage=1;return;
   }
   if(stage==1){Capture("offline-lobby");Check(UnityEngine.Object.FindFirstObjectByType<WebAccountService>()==null,"no account bridge object");Debug.Log("OFFLINE_UNITY_OK direct lobby fresh/resume/end maxima partner reload migration conflict corrupt original preservation no Firebase no queue");SessionState.SetBool(Flag,false);EditorApplication.Exit(0);stage=2;}
  }catch(Exception e){Debug.LogException(e);SessionState.SetBool(Flag,false);EditorApplication.Exit(1);}}
 }
